-- V1: Core schema for SkillNova AI
--
-- Design notes:
--   * Primary keys are UUIDs generated by the application (Hibernate), not the
--     database, so no pgcrypto/uuid-ossp extension is required.
--   * All child tables cascade delete with their parent roadmap/user so a
--     user or roadmap can be removed without leaving orphaned rows.
--   * Enumerated string columns are constrained with CHECK so invalid states
--     cannot be written even from outside the application layer.
--   * created_at/updated_at are set by the application; defaults here only
--     guard against rows inserted without the app layer (e.g. manual SQL).

CREATE TABLE users (
    id                      UUID PRIMARY KEY,
    email                   VARCHAR(255) NOT NULL,
    password_hash           VARCHAR(255) NOT NULL,
    full_name               VARCHAR(150) NOT NULL,
    current_job_role        VARCHAR(150),
    years_experience        NUMERIC(4,1),
    current_skills          TEXT,
    target_role             VARCHAR(150),
    daily_study_hours       NUMERIC(4,1),
    target_timeline_months  INTEGER,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_users_email UNIQUE (email)
);

CREATE TABLE roadmaps (
    id                      UUID PRIMARY KEY,
    user_id                 UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    target_role             VARCHAR(150) NOT NULL,
    current_job_role        VARCHAR(150),
    years_experience        NUMERIC(4,1),
    daily_study_hours       NUMERIC(4,1),
    target_timeline_months  INTEGER,
    status                  VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    ai_summary              TEXT,
    raw_ai_response         TEXT,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_roadmaps_status CHECK (status IN ('ACTIVE', 'COMPLETED', 'ARCHIVED'))
);

CREATE INDEX idx_roadmaps_user_id ON roadmaps (user_id);

CREATE TABLE roadmap_tasks (
    id                      UUID PRIMARY KEY,
    roadmap_id              UUID NOT NULL REFERENCES roadmaps (id) ON DELETE CASCADE,
    month_number            INTEGER NOT NULL,
    week_number             INTEGER,
    title                   VARCHAR(255) NOT NULL,
    description             TEXT,
    task_type               VARCHAR(30) NOT NULL,
    status                  VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    sort_order              INTEGER NOT NULL DEFAULT 0,
    completed_at            TIMESTAMPTZ,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_roadmap_tasks_type CHECK (task_type IN ('LEARNING', 'PROJECT', 'CERTIFICATION', 'INTERVIEW_PREP')),
    CONSTRAINT chk_roadmap_tasks_status CHECK (status IN ('PENDING', 'IN_PROGRESS', 'COMPLETED'))
);

CREATE INDEX idx_roadmap_tasks_roadmap_id ON roadmap_tasks (roadmap_id);

CREATE TABLE skill_gaps (
    id                      UUID PRIMARY KEY,
    roadmap_id              UUID NOT NULL REFERENCES roadmaps (id) ON DELETE CASCADE,
    skill_name              VARCHAR(150) NOT NULL,
    current_level           VARCHAR(30) NOT NULL,
    required_level          VARCHAR(30) NOT NULL,
    priority                VARCHAR(10) NOT NULL DEFAULT 'MEDIUM',
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_skill_gaps_current_level CHECK (current_level IN ('NONE', 'BEGINNER', 'INTERMEDIATE', 'ADVANCED', 'EXPERT')),
    CONSTRAINT chk_skill_gaps_required_level CHECK (required_level IN ('NONE', 'BEGINNER', 'INTERMEDIATE', 'ADVANCED', 'EXPERT')),
    CONSTRAINT chk_skill_gaps_priority CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH'))
);

CREATE INDEX idx_skill_gaps_roadmap_id ON skill_gaps (roadmap_id);

CREATE TABLE certification_recommendations (
    id                      UUID PRIMARY KEY,
    roadmap_id              UUID NOT NULL REFERENCES roadmaps (id) ON DELETE CASCADE,
    title                   VARCHAR(255) NOT NULL,
    provider                VARCHAR(150),
    url                     VARCHAR(500),
    priority                VARCHAR(10) NOT NULL DEFAULT 'MEDIUM',
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_certification_recommendations_priority CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH'))
);

CREATE INDEX idx_certification_recommendations_roadmap_id ON certification_recommendations (roadmap_id);

CREATE TABLE project_recommendations (
    id                      UUID PRIMARY KEY,
    roadmap_id              UUID NOT NULL REFERENCES roadmaps (id) ON DELETE CASCADE,
    title                   VARCHAR(255) NOT NULL,
    description             TEXT,
    difficulty              VARCHAR(20) NOT NULL DEFAULT 'INTERMEDIATE',
    tech_stack              VARCHAR(500),
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_project_recommendations_difficulty CHECK (difficulty IN ('BEGINNER', 'INTERMEDIATE', 'ADVANCED'))
);

CREATE INDEX idx_project_recommendations_roadmap_id ON project_recommendations (roadmap_id);
